/**
 * How `access:` reaches the Agent SDK (grammar 8.9, Decision D138).
 *
 * The SDK's containment primitive is a permission *mode* plus a working
 * directory, so the preset selects the mode and `cwd` carries the root. Which
 * primitive a preset lands on is **stated per harness and never implied
 * equivalent** (PRD resolved q57 ruling c): what `access:` means is the same
 * sentence under both harnesses, and what enforces it is each harness's own:
 *
 *  * `read_only` → `plan`, the mode whose system reminder the CLI wraps in its
 *    **read-only enforcement** preamble: the tree is readable and nothing under
 *    it is written. It is the one containment statement the SDK's own surface
 *    makes without a tool taxonomy this adapter would have had to invent, and
 *    the node's own instructions replace the mode's default
 *    code-implementation workflow body (`planModeInstructions`) so the run is
 *    asked for what the node asked for rather than for a plan to implement
 *    something;
 *  * `workspace_write` → `acceptEdits`, which auto-accepts edits under the
 *    working directory and still asks about everything else;
 *  * `full_access` → `bypassPermissions`, with the flag the SDK requires beside
 *    it, which is the preset that asks for no containment at all.
 */
const CC_PERMISSION: Readonly<Record<runtime.WorkspaceAccess, PermissionMode>> = {
  read_only: "plan",
  workspace_write: "acceptEdits",
  full_access: "bypassPermissions",
};

/**
 * Whether one resolved header value would forge a second header field.
 *
 * The compiler asks this of the text a composition **wrote** (`validate`
 * refuses it there, `invalid-value`); this asks it of what a `${ENV}` resolved
 * to, which is text no build ever saw and precisely the shape a gateway
 * deployment produces — an operator sets the variable, not the author.
 *
 * Every control character, not only the two that split a line: `\r` on its own
 * is a byte no header value carries either, and `\r\n` splits on the newline and
 * leaves the carriage return glued to the line before it. One shape, one rule —
 * the same answer the parser gives a written value and the same one a trigger's
 * `auth:` `prefix:` has always given.
 */
function forgesAHeaderField(value: string): boolean {
  for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index);
    if (code < 0x20 || code === 0x7f) return true;
  }
  return false;
}

/**
 * How a provider connection reaches this harness (grammar 8.9, Decision D143,
 * PRD resolved q58 ruling a).
 *
 * The SDK's own `Options` carry no endpoint and no credential — what they carry
 * is `env`, documented as **replacing** the subprocess environment outright —
 * and the Claude Code runtime that subprocess runs reads its connection out of
 * that environment. So all three facts are variables, merged into the `env` the
 * adapter already built from the node's own `env:`:
 *
 *  * `ANTHROPIC_BASE_URL` — the endpoint the bundled client is constructed with;
 *  * `ANTHROPIC_API_KEY` — the credential, read the same way. The **key** rather
 *    than the auth-token variable beside it, because what grammar 12.1 spells
 *    `api_key:` is a vendor API key; a gateway wanting a bearer token of its own
 *    writes it into `headers:`, which is resolved q25's own answer and arrives
 *    through the variable below;
 *  * `ANTHROPIC_CUSTOM_HEADERS` — one `Name: value` per line, which is how that
 *    runtime parses it.
 *
 * Three variables written, and **more than three owned**. That runtime reads a
 * whole endpoint table and a whole credential list — `ANTHROPIC_AUTH_TOKEN` is
 * sent as a bearer header beside the `X-Api-Key` the second variable sets, and
 * `CLAUDE_CODE_USE_BEDROCK` with its `ANTHROPIC_BEDROCK_BASE_URL` companion
 * chooses an endpoint instead of the first — so `validate` refuses a node `env:`
 * entry naming any of them for a fact this connection declares, not only the
 * three below — the whole family is the compiler's per-harness connection table
 * (grammar Decision D143, PRD resolved q58 rulings a and c). Nothing is filtered
 * here: by the time a run reaches this function the composition has already been
 * refused.
 *
 * **An absent fact sets no variable**, which is the half a one-token slip would
 * turn into the opposite of q25's ruling: a keyless gateway connection must
 * leave the credential variable *unset*, not set to the empty string, or the
 * harness would authenticate as nobody instead of letting the gateway do it.
 * `validate` has already refused a node whose provider declares a fact this
 * harness has no slot for, so there is nothing here to drop.
 *
 * **The header encoding is the one slot that can be handed a value it cannot
 * carry**, and this is where that is caught. `ANTHROPIC_CUSTOM_HEADERS` is
 * newline-delimited and each line is split on its first colon, so a value
 * carrying a line break would declare one header and send two — the second one
 * spelled by the value, which is `x-api-key` as easily as anything else.
 * `validate` refuses such a value where the composition *wrote* it, but a
 * `${ENV}` is text this build never saw and a gateway deployment is exactly
 * where operators set those variables (PRD resolved q58 ruling a). So the
 * resolved value is asked the same question here, and a run is failed rather
 * than quietly sent with a header nobody declared. The message names the node
 * and the header and **never the value**, which is `docs/trace.md` §11.1's rule
 * about every artifact this project writes: a connection header is where a
 * gateway credential lives.
 */
function ccConnection(run: runtime.HarnessRun): Record<string, string> {
  const held: Record<string, string> = {};
  const connection = run.connection;
  if (connection.baseUrl !== undefined) held["ANTHROPIC_BASE_URL"] = connection.baseUrl;
  if (connection.credential !== undefined) held["ANTHROPIC_API_KEY"] = connection.credential;
  const headers = Object.entries(connection.headers ?? {});
  if (headers.length > 0) {
    for (const [name, value] of headers) {
      if (forgesAHeaderField(value)) {
        throw new Error(
          `\`${run.node}\`'s connection header \`${name}\` resolves to a value carrying a control character: ` +
            "`ANTHROPIC_CUSTOM_HEADERS` is one `Name: value` per line, so the run would send a header the composition never declared",
        );
      }
    }
    held["ANTHROPIC_CUSTOM_HEADERS"] = headers.map(([name, value]) => `${name}: ${value}`).join("\n");
  }
  return held;
}

/**
 * The `cc` driver: a thin mapping over the Claude Agent SDK.
 *
 * # Where the top level is
 *
 * `parent_tool_use_id === null`. Every message the SDK yields carries it, and a
 * message produced *inside* a subagent carries that subagent's tool-use id — so
 * the one predicate is the whole of PRD resolved q57 ruling a's depth rule: a
 * subagent's turns and tool calls are yielded with no `tap` and reach the
 * journal payload only.
 *
 * # What enforces the allowlist
 *
 * **Two options, because one of them has a hole.** `tools` is the SDK's own
 * "base set of available built-in tools", so a list written there is a tool set
 * the model is never offered — a bound that holds whatever the permission mode
 * is. `canUseTool` denies, per call, anything outside the list that reached the
 * loop anyway, and tapes the denial as a `"refused"` tool event so the trace
 * says the bound bit; `allowedTools` auto-allows the ones inside it so a bounded
 * run is not also a prompting one.
 *
 * The hole is `access: full_access`, and it is why `tools` carries the bound
 * rather than the callback: that preset is `permissionMode: "bypassPermissions"`,
 * which the SDK documents as bypassing **all** permission checks — so
 * `canUseTool` does not run, and a node whose `enforcesTools` says its list is
 * enforced would be asserting a bound nothing held (grammar 8.9, PRD resolved
 * q57 ruling c). Narrowing the available set is the answer the SDK's own
 * documentation gives for `allowedTools`: "to restrict which tools are
 * available, use the `tools` option instead".
 *
 * # Whose system prompt a run has
 *
 * The harness's, with the node's `prompt:` **appended** to it
 * (`{ type: "preset", preset: "claude_code", append }`). A bare string there is
 * the SDK's custom-prompt form and *replaces* the preset — and the preset is
 * the vendor's own agent instructions, which is half of what PRD resolved q57
 * makes this a kind for: the loop, the tool shapes and the prompt the model was
 * post-trained against are the thing that cannot be reassembled from parts. So
 * the node's prompt is what it reads like in the grammar — instructions *for*
 * the harness — rather than a replacement of the harness.
 *
 * # What is asked for, and what is parsed
 *
 * `outputFormat: { type: "json_schema" }` carrying the schema the adapter
 * already projected through this harness's lowering table, and the answer
 * arrives as the result message's `structured_output`. The adapter parses it
 * against the **full** declared schema, which is where PRD resolved q55's
 * amendment to q16 lives.
 */
const CC_DRIVER: runtime.HarnessDriver = {
  sdk: "@anthropic-ai/claude-agent-sdk",
  version: CC_SDK_VERSION,
  enforcesTools: true,
  run(run: runtime.HarnessRun): AsyncIterable<runtime.HarnessEvent> {
    return (async function* driven(): AsyncGenerator<runtime.HarnessEvent> {
      // What the permission callback refused, drained into the stream between
      // messages: `canUseTool` answers the SDK rather than this generator, so a
      // queue is how a denial becomes a tool event in the order it happened.
      const refusals: runtime.HarnessEvent[] = [];
      // The name each top-level `tool_use` went out under, so the `tool_result`
      // that answers it can be taped under the same name.
      const calls = new Map<string, string>();
      // The `tool_use` ids the callback below denied. A denial is taped once,
      // from the callback; the `tool_result` the SDK then hands the model is
      // that same denial travelling back, and taping it again would claim two
      // tool events where the run made one (`docs/trace.md` 7.6.3, whose
      // `completed` and `failed` describe a call that executed).
      const refused = new Set<string>();

      const config = ccOptions(run, refusals, refused);

      for await (const message of query({ prompt: run.input, options: config })) {
        while (refusals.length > 0) yield refusals.shift() as runtime.HarnessEvent;
        yield* ccEvents(message, calls, refused);
      }
      while (refusals.length > 0) yield refusals.shift() as runtime.HarnessEvent;
    })();
  },
};

/**
 * The `Options` one `cc` run is made of — the config map of grammar 8.9, as one
 * value (see [`CC_DRIVER`]).
 *
 * **Exported for the reason [`scriptedDriver`] is**: what this object holds is
 * the whole of the node's containment, and none of it is visible from a run's
 * answer or from the events a driver yields. A test that could only drive the
 * seam could say nothing about the bound at all — and the bound that matters
 * most, the [`CC_RESERVED`] drop, is a *subtraction*: it is what a settings key
 * did **not** put here. So the options are built by a function a test can call
 * and then read, against a `run` whose `settings` spell every bound this node
 * states, rather than assembled inline where only the vendor's SDK ever sees
 * them.
 *
 * `refusals` and `refused` are the driver's own two queues, handed in because
 * the permission callback below writes to both: a denial is an event the
 * generator drains between messages, and an id the `tool_result` that answers
 * it is told apart by.
 */
export function ccOptions(
  run: runtime.HarnessRun,
  refusals: runtime.HarnessEvent[],
  refused: Set<string>,
): Options {
  const options: Options = {
    cwd: run.workspace,
    systemPrompt: { type: "preset", preset: "claude_code", append: run.instructions },
    model: run.model,
    permissionMode: CC_PERMISSION[run.access],
    abortController: controllerFor(run.signal),
    // The node's declared environment, with the model's connection mapped over
    // the top. The order is not a precedence rule: `validate` refuses an `env:`
    // entry spelling a variable this map sets — or one this runtime reads for
    // the same fact beside it, which is the half a merge order could not have
    // fixed anyway — so the two never decide one fact (PRD resolved q58 ruling
    // c).
    env: { ...run.env, ...ccConnection(run) },
    outputFormat: { type: "json_schema", schema: { ...run.schema } },
    ...passthrough(run, CC_SETTINGS, CC_RESERVED),
  };
  if (run.access === "full_access") options.allowDangerouslySkipPermissions = true;
  // Plan mode's body, replaced by what this node asked for: the mode's
  // default body is a code-implementation workflow, and a `read_only` node
  // is a run that reads and reports (see [`CC_PERMISSION`]).
  if (run.access === "read_only") options.planModeInstructions = run.instructions;
  // The one `model.*` setting this harness has a place for: the `anthropic`
  // plugin's `thinking: { budget_tokens: … }` is the SDK's
  // `maxThinkingTokens` (Decision D141).
  const thinking = run.modelSettings["thinking"];
  const budgetTokens =
    typeof thinking === "object" && thinking !== null
      ? settingNumber((thinking as Record<string, unknown>)["budget_tokens"])
      : undefined;
  if (budgetTokens !== undefined) options.maxThinkingTokens = budgetTokens;
  const maxTurns = settingNumber(run.settings["max_turns"]);
  if (maxTurns !== undefined) options.maxTurns = maxTurns;
  const budget = settingNumber(run.settings["max_budget_usd"]);
  if (budget !== undefined) options.maxBudgetUsd = budget;
  const forward = settingFlag(run.settings["forward_subagent_text"]);
  if (forward !== undefined) options.forwardSubagentText = forward;
  const disallowed = settingList(run.settings["disallowed_tools"]);
  if (disallowed !== undefined) options.disallowedTools = disallowed;
  const allowed = run.allowTools;
  if (allowed !== undefined) {
    // The bound itself: a tool outside the list is not in the set the loop
    // can reach, which is true under every one of the three `access:`
    // presets — `bypassPermissions` included.
    options.tools = [...allowed];
    options.allowedTools = [...allowed];
    options.canUseTool = (name, _input, ask) => {
      if (allowed.includes(name)) return Promise.resolve({ behavior: "allow" as const });
      const message = `\`${run.node}\` allows ${allowed.map((tool) => `\`${tool}\``).join(", ")}, and \`${name}\` is not one of them`;
      // The call this denial answers, remembered by its id: the SDK hands
      // the model the denial as the `tool_result` for that `tool_use`, and
      // one call is one tool event.
      refused.add(ask.toolUseID);
      refusals.push({
        source: { type: "agent-compose.permission_denied", tool: name, message },
        // A denial inside a **subagent** is that subagent's, and the
        // envelope carries the top level only — the same depth rule
        // [`ccEvents`] reads off `parent_tool_use_id`, read here off the
        // sub-agent id the SDK passes the callback (PRD resolved q57
        // ruling a).
        ...(ask.agentID === undefined
          ? { tap: { kind: "tool" as const, name, outcome: "refused" as const, error: message } }
          : {}),
      });
      return Promise.resolve({ behavior: "deny" as const, message });
    };
  }
  return options;
}

/** One SDK message, as the events the tap reads (see [`CC_DRIVER`]). */
function* ccEvents(
  message: SDKMessage,
  calls: Map<string, string>,
  refused: Set<string>,
): Generator<runtime.HarnessEvent> {
  // A message from inside a subagent is payload and nothing else — the depth
  // rule PRD resolved q57 ruling a fixes, read off the one field that carries
  // it.
  const nested =
    "parent_tool_use_id" in message && (message as { parent_tool_use_id: unknown }).parent_tool_use_id !== null;
  if (nested) {
    yield { source: message };
    return;
  }
  if (message.type === "assistant") {
    const blocks = Array.isArray(message.message.content) ? message.message.content : [];
    for (const block of blocks) {
      if (block.type === "tool_use") calls.set(block.id, block.name);
    }
    yield { source: message, tap: { kind: "turn" } };
    return;
  }
  if (message.type === "user") {
    const blocks = Array.isArray(message.message.content) ? message.message.content : [];
    yield { source: message };
    for (const block of blocks) {
      if (block.type !== "tool_result") continue;
      const name = calls.get(block.tool_use_id);
      if (name === undefined) continue;
      // A call the permission callback denied was taped `refused` there, and
      // this result is that denial on its way to the model rather than a second
      // event: the call never executed, so neither `completed` nor `failed`
      // describes it (`docs/trace.md` 7.6.3). The message still reaches the
      // journal's payload above, untapped, like every other result.
      if (refused.delete(block.tool_use_id)) {
        calls.delete(block.tool_use_id);
        continue;
      }
      const failed = block.is_error === true;
      yield {
        source: { type: "agent-compose.tool_result", tool: name, is_error: failed },
        tap: {
          kind: "tool",
          name,
          outcome: failed ? "failed" : "completed",
          ...(failed ? { error: `the tool result came back as an error` } : {}),
        },
      };
    }
    return;
  }
  if (message.type === "result") {
    const usage = message.usage as { input_tokens?: number; output_tokens?: number };
    yield {
      source: message,
      tap: {
        kind: "settled",
        cost: {
          ...(typeof usage.input_tokens === "number" ? { inputTokens: usage.input_tokens } : {}),
          ...(typeof usage.output_tokens === "number" ? { outputTokens: usage.output_tokens } : {}),
          ...(typeof message.total_cost_usd === "number" ? { usd: message.total_cost_usd } : {}),
        },
        // The two facts `codex` has no shape for: which of the SDK's result
        // subtypes this was, and the stop reason underneath it.
        extra: { subtype: message.subtype, stopReason: message.stop_reason },
      },
    };
    if (message.subtype !== "success") {
      yield {
        source: { type: "agent-compose.result_error", subtype: message.subtype },
        tap: { kind: "error", message: `the run ended \`${message.subtype}\`` },
      };
      return;
    }
    if (message.structured_output !== undefined) {
      yield {
        source: { type: "agent-compose.structured_output" },
        tap: { kind: "output", value: message.structured_output },
      };
    }
    return;
  }
  yield { source: message };
}

/**
 * The `codex` SDK version this compiler release pins — the number `package.json` declares and the number a `HarnessRecord` reports.
 */
const CODEX_SDK_VERSION: string = "0.154.0";

/**
 * The keys of a `codex` node's `settings:` this compiler release maps by name
 * (Decision D140's first tier).
 *
 * Everything else travels to the thread's options unchanged, under the warning
 * `validate` printed for it — PRD resolved q30's terms, one construct along.
 */
const CODEX_SETTINGS: readonly string[] = [
  "network_access",
  "web_search",
  "skip_git_repo_check",
];

/**
 * The keys of a thread's options the **adapter** owns, and which a `settings:`
 * key therefore never reaches (see [`passthrough`]).
 *
 * Two kinds of name are on the list, exactly as on `cc`'s:
 *
 *  * an option that **spells** a bound some other part of the node states:
 *    `workspace:` is `workingDirectory`, `access:` is `sandboxMode` and the
 *    approval policy beside it, and `model:` is the model and the one reasoning
 *    setting Decision D141 maps into it. A composition that spelled one of them
 *    here would be reaching around the construct that states it, through the
 *    surface this grammar deliberately leaves open — so these are dropped
 *    rather than passed. The environment is not on the list because it is not a
 *    thread option at all, and neither is the model's **connection**: both are
 *    the *client's*, built by [`codexClient`] from a literal that no
 *    `settings:` key reaches;
 *  * an option that **contains** one without spelling it, which is the wider
 *    half of the dropped set grammar 8.9 states: `additionalDirectories` is
 *    additional sandbox roots beside `workspace:`, so a run under it is written
 *    where the node's own workspace never reached. It is the same option `cc`
 *    drops by the same name, and the two harnesses answer that key the same way
 *    or `access:` means one thing under one harness and another under the
 *    other.
 *
 * `approvalPolicy` is the one that is neither: it is the **per-call approval
 * tier** PRD resolved q57 ruling c says this release does not adopt, and a run
 * that escalated out of its sandbox to an approver nothing answers for would be
 * `access:` saying one thing and the run doing another. The thread's other
 * options are the vendor's own vocabulary and travel unchanged, which is
 * Decision D140's whole point.
 *
 * The list is audited against the pinned SDK's own `ThreadOptions`, which is
 * what `a_reserved_list_is_audited_against_the_pinned_option_surface`
 * (`codegen/harness.rs`) holds it to.
 */
const CODEX_RESERVED: readonly string[] = [
  // Options that spell a bound another key states.
  "approvalPolicy",
  "model",
  "modelReasoningEffort",
  "sandboxMode",
  "workingDirectory",
  // …and the option that contains one without spelling it.
  "additionalDirectories",
];

/**
 * How `access:` reaches the Codex SDK (grammar 8.9, Decision D138).
 *
 * One-to-one with its own sandbox presets, which is why this grammar's three
 * names are the three they are: `codex` is the harness whose containment
 * primitive is named, and a vocabulary that did not line up with it would be a
 * translation nobody could check.
 */
const CODEX_SANDBOX: Readonly<Record<runtime.WorkspaceAccess, SandboxMode>> = {
  read_only: "read-only",
  workspace_write: "workspace-write",
  full_access: "danger-full-access",
};

/**
 * The `codex` driver: a thin mapping over the Codex SDK.
 *
 * # Where the top level is
 *
 * Everywhere. `runStreamed` yields one thread's events, and a Codex thread has
 * no nesting for PRD resolved q57 ruling a's depth rule to cut at: what its
 * `mcp_tool_call` items reach is another process's, not a subagent of this run.
 * So every turn and every tool item this stream carries is a top-level one, and
 * the ruling's boundary is satisfied by there being nothing below it.
 *
 * # What bounds a run, and what does not
 *
 * The **sandbox**, and nothing else. The Codex SDK's per-call approval tier is
 * their app server's, which this release does not adopt, so `enforcesTools` is
 * `false` and `docs/grammar.md` 8.9 states the asymmetry where an author writes
 * the list. The `codex` half of PRD resolved q57 ruling c is this constant.
 *
 * `allow_tools:` is therefore what the harness is **offered**, and offering it
 * is something a driver has to do rather than something that happens: a thread
 * has no tool-set option to put it in, so the list reaches the run the one way
 * anything reaches it — as a line of the instructions the turn carries
 * ([`codexTurn`]). A list that reached nothing at all would make grammar 8.9's
 * `offered` a word for a key with no effect.
 *
 * # What is asked for, and what is parsed
 *
 * `outputSchema`, carrying the schema the adapter already projected through this
 * harness's lowering table; the answer arrives as the last `agent_message`
 * item's text, which the SDK documents as JSON when a schema was asked for. The
 * adapter parses it against the **full** declared schema (PRD resolved q55).
 */
const CODEX_DRIVER: runtime.HarnessDriver = {
  sdk: "@openai/codex-sdk",
  version: CODEX_SDK_VERSION,
  enforcesTools: false,
  run(run: runtime.HarnessRun): AsyncIterable<runtime.HarnessEvent> {
    return (async function* driven(): AsyncGenerator<runtime.HarnessEvent> {
      const codex = new Codex(codexClient(run));
      const thread = codex.startThread(codexOptions(run));
      const streamed = await thread.runStreamed(codexTurn(run), {
        outputSchema: { ...run.schema },
        signal: run.signal,
      });

      // The totals, accumulated: `codex` reports usage per turn and no money at
      // all, so the rollup is a sum of what the turns said rather than a number
      // the SDK hands over (PRD resolved q57 ruling a).
      let inputTokens = 0;
      let outputTokens = 0;
      let cached = 0;
      let cacheWrites = 0;
      let answer: string | undefined;

      for await (const event of streamed.events) {
        switch (event.type) {
          case "turn.completed": {
            const usage = event.usage;
            inputTokens += usage.input_tokens;
            outputTokens += usage.output_tokens;
            cached += usage.cached_input_tokens;
            cacheWrites += usage.cache_write_input_tokens;
            yield {
              source: event,
              tap: {
                kind: "turn",
                usage: {
                  inputTokens: usage.input_tokens,
                  cachedInputTokens: usage.cached_input_tokens,
                  outputTokens: usage.output_tokens,
                  reasoningTokens: usage.reasoning_output_tokens,
                },
              },
            };
            break;
          }
          case "turn.failed":
            yield { source: event, tap: { kind: "error", message: event.error.message } };
            break;
          case "error":
            yield { source: event, tap: { kind: "error", message: event.message } };
            break;
          case "item.completed": {
            const tap = codexToolTap(event.item);
            if (event.item.type === "agent_message") answer = event.item.text;
            yield tap === undefined ? { source: event } : { source: event, tap };
            break;
          }
          default:
            yield { source: event };
            break;
        }
      }

      yield {
        source: { type: "agent-compose.settled" },
        tap: {
          kind: "settled",
          cost: { inputTokens, outputTokens },
          // The two counters `cc` has no shape for.
          extra: { cachedInputTokens: cached, cacheWriteInputTokens: cacheWrites },
        },
      };
      if (answer !== undefined) {
        yield {
          source: { type: "agent-compose.agent_message" },
          tap: { kind: "output", value: codexAnswer(answer) },
        };
      }
    })();
  },
};

/**
 * The `CodexOptions` this run's client is built from: the scrubbed environment,
 * and the model's connection (grammar 8.9, Decisions D139, D143).
 *
 * **The environment** is handed to the SDK rather than inherited by it: the
 * Codex SDK documents that a provided `env` replaces `process.env` for the CLI
 * it spawns, which is exactly the scrubbed child PRD resolved q54 ruling b asks
 * for.
 *
 * **The connection** is this harness's own surface, and it is the *client's*
 * rather than a thread's: `baseUrl`, which the SDK passes to the CLI as
 * `--config openai_base_url=…`, and `apiKey`, which it sets as `CODEX_API_KEY`
 * in that same environment on its way past. There is **no header slot** on
 * either object, which is why a provider declaring `headers:` is refused at
 * `validate` for a node bound to this harness rather than quietly dropped here
 * (PRD resolved q58 ruling b) — a faked one would have meant composing a
 * `model_providers.*` config table the composition never wrote.
 *
 * An absent fact sets no key at all, resolved q25's posture: a keyless gateway
 * connection leaves `apiKey` undefined, and the SDK then sets no `CODEX_API_KEY`
 * for the CLI to authenticate with.
 *
 * **Exported for the reason [`codexOptions`] is**, and for one more: what this
 * object holds is the whole of where the run's traffic goes, and none of it is
 * visible from a run's answer or from the events the driver yields.
 *
 * It is built from a literal and from `run.connection` alone. Nothing here reads
 * `run.settings`, because [`passthrough`] feeds the **thread** and a key that
 * could reach this object would be choosing the client — `codexPathOverride` is
 * on it, and so is the `config` escape hatch — which is what
 * `what_program_a_harness_run_is_cannot_be_chosen_by_a_settings_key` holds.
 */
export function codexClient(run: runtime.HarnessRun): CodexOptions {
  const connection = run.connection;
  return {
    env: { ...run.env },
    ...(connection.baseUrl === undefined ? {} : { baseUrl: connection.baseUrl }),
    ...(connection.credential === undefined ? {} : { apiKey: connection.credential }),
  };
}

/**
 * The `ThreadOptions` one `codex` run is made of — the config map of grammar
 * 8.9, as one value (see [`CODEX_DRIVER`]).
 *
 * **Exported for the reason [`scriptedDriver`] is**, and the same reason
 * [`ccOptions`] is under the other harness: this object is where `workspace:`
 * and `access:` become this harness's own containment primitive, and none of it
 * is visible from a run's answer or from the events the driver yields. The
 * bound worth a test most of all is the [`CODEX_RESERVED`] drop, which is a
 * *subtraction* — what a `settings:` key did **not** put here — and a
 * subtraction can only be read off the object itself.
 */
export function codexOptions(run: runtime.HarnessRun): ThreadOptions {
  const options: ThreadOptions = {
    model: run.model,
    workingDirectory: run.workspace,
    sandboxMode: CODEX_SANDBOX[run.access],
    ...passthrough(run, CODEX_SETTINGS, CODEX_RESERVED),
  };
  const effort = settingText(run.modelSettings["reasoning_effort"]);
  if (effort !== undefined) {
    options.modelReasoningEffort = effort as ThreadOptions["modelReasoningEffort"];
  }
  const network = settingFlag(run.settings["network_access"]);
  if (network !== undefined) options.networkAccessEnabled = network;
  const search = settingText(run.settings["web_search"]);
  if (search !== undefined) options.webSearchMode = search as ThreadOptions["webSearchMode"];
  const skipGit = settingFlag(run.settings["skip_git_repo_check"]);
  if (skipGit !== undefined) options.skipGitRepoCheck = skipGit;
  return options;
}

/**
 * The turn one run sends: the node's instructions, the list it offers the
 * harness where it wrote one, and the bound input (see [`CODEX_DRIVER`]).
 *
 * The instructions lead, the way they do under the other harness, and the
 * vendor's own base instructions are untouched beneath them — a thread keeps
 * the agent loop it was post-trained with, which is why this is a kind at all
 * (PRD resolved q57).
 *
 * The offered list is stated as what it is: this harness bounds at the sandbox,
 * so the sentence is an instruction the model reads and not a bound. `cc` puts
 * the same list somewhere that holds; `docs/grammar.md` 8.9 and the graph
 * document's `tools_enforced` are where the asymmetry is written down.
 */
function codexTurn(run: runtime.HarnessRun): string {
  const offered =
    run.allowTools === undefined
      ? ""
      : `\n\nThe tools this run is offered: ${run.allowTools.join(", ")}. Use no others.`;
  return `${run.instructions}${offered}\n\n${run.input}`;
}

/**
 * One completed thread item, as a tool event — or `undefined` where the item is
 * not a tool at all.
 *
 * Four of the SDK's eight item types are tool events; the other four are the
 * agent's own message, its reasoning, its to-do list and a non-fatal error,
 * none of which is a call to anything. Their events still reach the payload:
 * this decides what the **trace** carries, not what the journal holds.
 */
function codexToolTap(item: ThreadItem): runtime.HarnessTap | undefined {
  switch (item.type) {
    case "command_execution":
      return {
        kind: "tool",
        name: "command_execution",
        outcome: item.status === "failed" ? "failed" : "completed",
        ...(item.status === "failed"
          ? { error: `the command exited ${item.exit_code ?? "without a status"}` }
          : {}),
      };
    case "file_change":
      return {
        kind: "tool",
        name: "file_change",
        outcome: item.status === "failed" ? "failed" : "completed",
        ...(item.status === "failed" ? { error: "the patch did not apply" } : {}),
      };
    case "mcp_tool_call":
      return {
        kind: "tool",
        name: `${item.server}/${item.tool}`,
        outcome: item.status === "failed" ? "failed" : "completed",
        ...(item.error === undefined ? {} : { error: item.error.message }),
      };
    case "web_search":
      return { kind: "tool", name: "web_search", outcome: "completed" };
    default:
      return undefined;
  }
}

/**
 * The agent's last message, as the value the gate is handed.
 *
 * The SDK documents an `agent_message`'s `text` as JSON when `outputSchema` was
 * asked for, so the text is decoded here. A text that is **not** JSON is handed
 * on as the string it is rather than being refused here: what an answer has to
 * be is the node's `output:` schema, and the gate is the one place that decides
 * it — a driver that refused first would report a decoding failure where the
 * composition's own contract has a message to give (PRD resolved q55 ruling c).
 */
function codexAnswer(text: string): unknown {
  try {
    return JSON.parse(text) as unknown;
  } catch {
    return text;
  }
}

/**
 * The drivers this composition uses, by harness — what `runtime.runCoder` resolves a `coder:` node's harness against.
 *
 * A harness with no driver here is one no node binds, and a run that reached one would be `runtime.HarnessUnavailable`: the adapter refuses at the call rather than dispatching into nothing.
 */
export const DRIVERS: runtime.HarnessDrivers = {
  cc: CC_DRIVER,
  codex: CODEX_DRIVER,
};
